-- YottaFlex Predictive Maintenance SQL seed
-- High-volume telemetry remains in CSV files.

BEGIN TRANSACTION;;
CREATE TABLE "failure_events" ("failure_id" TEXT, "machine_id" TEXT, "failure_type" TEXT, "root_cause" TEXT, "severity" TEXT, "symptom_start_at" TEXT, "failure_at" TEXT, "detected_at" TEXT, "ground_truth_label" INTEGER, PRIMARY KEY ("failure_id"), FOREIGN KEY ("machine_id") REFERENCES "machines"("machine_id"));;
CREATE TABLE "ground_truth" ("telemetry_id" TEXT, "failure_id" TEXT, "machine_id" TEXT, "failure_type" TEXT, "ground_truth_label" INTEGER, "symptom_start_at" TEXT, "failure_at" TEXT, FOREIGN KEY ("failure_id") REFERENCES "failure_events"("failure_id"), FOREIGN KEY ("machine_id") REFERENCES "machines"("machine_id"));;
CREATE TABLE "machines" ("machine_id" TEXT, "line_id" TEXT, "machine_type" TEXT, "machine_status" TEXT, PRIMARY KEY ("machine_id"), FOREIGN KEY ("line_id") REFERENCES "production_lines"("line_id"));;
CREATE TABLE "maintenance_status_history" ("status_event_id" TEXT, "work_order_id" TEXT, "machine_id" TEXT, "previous_status" TEXT, "new_status" TEXT, "event_timestamp" TEXT, PRIMARY KEY ("status_event_id"), FOREIGN KEY ("work_order_id") REFERENCES "maintenance_work_orders"("work_order_id"), FOREIGN KEY ("machine_id") REFERENCES "machines"("machine_id"));;
CREATE TABLE "maintenance_work_orders" ("work_order_id" TEXT, "failure_id" TEXT, "machine_id" TEXT, "technician_id" TEXT, "maintenance_type" TEXT, "priority" TEXT, "opened_at" TEXT, "started_at" TEXT, "completed_at" TEXT, "work_order_status" TEXT, "repair_duration_hours" REAL, "downtime_hours" REAL, PRIMARY KEY ("work_order_id"), FOREIGN KEY ("failure_id") REFERENCES "failure_events"("failure_id"), FOREIGN KEY ("machine_id") REFERENCES "machines"("machine_id"), FOREIGN KEY ("technician_id") REFERENCES "technicians"("technician_id"));;
CREATE TABLE "operating_shifts" ("shift_code" TEXT, "shift_name" TEXT, "start_time" TEXT, "end_time" TEXT, "timezone" TEXT, PRIMARY KEY ("shift_code"));;
CREATE TABLE "parts" ("part_id" TEXT, "part_name" TEXT, "unit_cost" REAL, "unit" TEXT, PRIMARY KEY ("part_id"));;
CREATE TABLE "plants" ("plant_id" TEXT, "plant_name" TEXT, "location" TEXT, PRIMARY KEY ("plant_id"));;
CREATE TABLE "production_lines" ("line_id" TEXT, "plant_id" TEXT, "line_name" TEXT, PRIMARY KEY ("line_id"), FOREIGN KEY ("plant_id") REFERENCES "plants"("plant_id"));;
CREATE TABLE "sensors" ("sensor_id" TEXT, "machine_id" TEXT, "sensor_type" TEXT, "unit" TEXT, "min_value" REAL, "max_value" REAL, PRIMARY KEY ("sensor_id"), FOREIGN KEY ("machine_id") REFERENCES "machines"("machine_id"));;
CREATE TABLE "technicians" ("technician_id" TEXT, "technician_name" TEXT, "specialization" TEXT, "availability_status" TEXT, PRIMARY KEY ("technician_id"));;
CREATE TABLE "work_order_parts" ("work_order_id" TEXT, "part_id" TEXT, "quantity_used" INTEGER, "unit_cost" REAL, PRIMARY KEY ("work_order_id", "part_id"), FOREIGN KEY ("work_order_id") REFERENCES "maintenance_work_orders"("work_order_id"), FOREIGN KEY ("part_id") REFERENCES "parts"("part_id"));;
COMMIT;;
